insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (146, 'Your Birthday Was the Best!', 'Hutchings, Maggie', NULL, 'and UNICORN! and one of the world''s hottest new picture-book illustrators comes the story of a plucky young cockroach who gate-crashes a birthday party - with hilarious results. Funny, silly and surprisingly cute, YOUR BIRTHDAY WAS THE BEST! is the perfect blend of downright gross and delightfully entertaining.', 'verified', '146_your_birthday_was_the_best.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (147, 'The Giant and the Sea', 'Jamieson, Trent', NULL, 'A giant stands on the shore, watching the sea. She never moves, never speaks, until the day she turns to a little girl and says, ''The sea is rising.'' The brave girl takes the message to the town. But when the people refuse to listen, the giant must find another way to save them. Perfect for the children of the Climate Strike, this is a lyrical and deeply moving story about climate change, standing up for what you believe in, and the power of hope. Winner of the 2021 Environment Award for Children''s Literature', 'verified', '147_the_giant_and_the_sea.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (148, 'Stuck', 'Jeffers, Oliver', 'Oliver Jeffers', 'When Floyd''s kite gets stuck in a tree, he''s determined to get it out. But how? Well, by knocking it down with his shoe, of course. But strangely enough, it too gets stuck. And the only logical course of action . . . is to throw his other shoe. Only now it''s stuck! Surely there must be something he can use to get his kite unstuck. An orangutan? A boat? His front door? Yes, yes, and yes. And that''s only the beginning. Stuck is Oliver Jeffers'' most absurdly funny story since The Incredible Book-Eating Boy. Childlike in concept and vibrantly illustrated as only Oliver Jeffers could, here is a picture book worth rescuing from any tree.', 'verified', '148_stuck.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (149, 'The Boy Who Harnessed the Wind', 'Kamkwamba, William', NULL, 'When a terrible drought struck William Kamkwamba''s tiny village in Malawi, his family lost all of the season''s crops, leaving them with nothing to eat and nothing to sell. William began to explore science books in his village library, looking for a solution. There, he came up with the idea that would change his family''s life forever: he could build a windmill. Made out of scrap metal and old bicycle parts, William''s windmill brought electricity to his home and helped his family pump the water they needed to farm the land. Retold for a younger audience, this exciting memoir shows how, even in a desperate situation, one boy''s brilliant idea can light up the world. Complete with photographs, illustrations, and an epilogue that will bring readers up to date on William.', 'verified', '149_the_boy_who_harnessed_the_wind.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (150, 'Two Hands Together', 'Kidd, Diana', NULL, 'When the Rileys move in next door, Lily and Ella become the best of friends. But Lily can''t understand why her Dad doesn''t like the Rileys. Why doesn''t he want them to go over there? Why is he being so horrible and mean? Does something big have to happen to change his mind?', 'verified', '150_two_hands_together.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (151, 'Onion Tears', 'Kidd, Diana', NULL, 'Nam-Huong tries to come to terms with her grief over the loss of her family as she starts a new life in America.', 'verified', '151_onion_tears.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (152, 'Three', 'King, Stephen Mihael', NULL, 'Roland of Gilead, the Last Gunslinger, encounters four doors which open to 1980s America, where he joins forces with the defiant Eddie Dean and courageous, volatile Odetta Holmes. And confronts deadly serial killer Jack Mort. As the titanic forces gather, a savage struggle between underworld evil and otherworldly enemies conspire to bring an end to Roland''s quest for the Dark Tower... Masterfully weaving dark fantasy and icy realism, THE DRAWING OF THE THREE compulsively propels readers toward the next chapter. And the Tower is closer...', 'verified', '152_three.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (153, 'My Two Blankets', 'Kobald, Irena', NULL, 'When a little girl nicknamed "Cartwheel" moves to a different country with her family to be safe she has a hard time adjusting to her new home.', 'verified', '153_my_two_blankets.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (154, 'All About the Heart', 'Kowalski, Remi', NULL, 'Does your heart really stop when you sneeze? Can it break? How does our heart compare to the heart of other creatures? Curious kids will find the answers to all their questions and more in All About the Heart by paediatric cardiologist Dr Remi Kowalski. This is the first book in a nonfiction series Berbay is launching, authored my paediatric medical experts in their fields. Presented in a kid-friendly, exciting way, these books - which can be read cover to cover - are designed to help kids better understand the way their bodies work and appreciate how incredible they are.', 'verified', '154_all_about_the_heart.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (155, 'The Biscuit Maker', 'Lawson, Sue', NULL, 'In Mavin Road, there''s no time for hellos or chats until a lonely and mysterious biscuit maker''s magic brings everyone together. Benedict Stanley lives alone with his cat in Mavin Road where families hustle, joggers puff and workers scurry to the train, and no one has time for anyone else. So Benedict begins making biscuits to mark moments in all their lives, leaving them secretly at their doors. People start talking. Who is this mysterious biscuit maker? When Benedict falls ill, young Rory, the only person to know his secret, gathers the residents of Mavin Road and brings them to his door. A beautiful, heartwarming book that celebrates community and human connection.', 'verified', '155_the_biscuit_maker.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (156, 'A is for Australian Reefs: A Factastic Tour', 'Lessac, Frane', NULL, 'Along the coastline of Australia, underwater reefs are bustling with the most amazing sea creatures living on the planet! A deep dive into the biodiversity of Australia''s remarkable coastline from sharks to octopuses to dolphins and manta rays and seahorses - and the most famous reef of all - the Great Barrier Reef.', 'verified', '156_a_is_for_australian_reefs_a_factastic_tour.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (157, 'Frederick', 'Lionni, Leo', NULL, 'Frederick the field mouse stores up something special for the long cold winter.', 'verified', '157_frederick.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (158, 'The Alphabet Tree', 'Lionni, Leo', NULL, 'A strong wind blows most of the letters off the alphabet tree and those that remain hide among the branches. Then a bug and a caterpillar come along and teach them how to arrange themselves into words and sentences to form a special message.', 'verified', '158_the_alphabet_tree.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (159, 'Water Dance', 'Locker, Thomas', NULL, 'Whooshing. Surging. Roaring. Trickling. Calming. Water.', 'verified', '159_water_dance.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (160, 'Sky Tree', 'Locker, Thomas', NULL, 'A tree stands on a hill by a river, its branches showing the seasons, filling with changing leaves, clouds, snow, birds, mist, fog, and the spring sun.', 'verified', '160_sky_tree.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (161, 'A Little Golden Book Biography - Taylor Swift', 'Loggia, Wendy', NULL, 'Celebrate global superstar Taylor Swift with this collectible Little Golden Book, which tells her inspiring life story alongside gorgeous original illustrations! With full-color illustrations on every page, Taylor Swift: A Little Golden Book Biography brings her story to life-from her childhood living on a Christmas tree farm, where she discovered her passion for songwriting, to her early days on Nashville''s Music Row and her rise as one of the biggest stars in pop music. When you''re Taylor Swift, the sky''s the limit!', 'verified', '161_a_little_golden_book_biography_taylor_swift.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (162, 'Walking in Gagudju Country: Exploring the Monsoon Forest', 'Lucas, Diane & Tyler, Ben', NULL, 'When we go walking, we never know how long we will be, what we will hear and what we will see. We pack our bags with food and water, a billy and some matches to light a fire. We head off into the shady monsoon forest on the edge of the billabong. Diane Lucas, Ben Tyler and Emma Long share their knowledge and love of the Top End in this enchanting and accessible book about one of Australia''s most ancient and beautiful ecosystems. ''This information-laden book, complete with glossary, brims with life, beauty and magic. It is a delightful read for primary school children.'' Books+Publishing', 'verified', '162_walking_in_gagudju_country_exploring_the_monsoon_forest.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (163, 'The Raven''s Song', 'Macdibble, Bren & Fraillon, Zana', NULL, 'A wonderful children''s novel by two stellar writers featuring Shelby and Phoenix, living 100 years apart yet unexpectedly joined across time - and each make the discovery of a lifetime that has the potential to upend their worlds. HONOUR BOOK: 2022 CBCA Book of the Year, Younger ReadersSHORTLISTED: 2023 WA Premier''s Prize for Children''s Book of the YearSHORTLISTED: 2024 NSW Premier''s Literary Awards, Patricia Wrightson Prize for Children''s Literature ''This is how we have to live now.'' Shelby and her best friend Davy live quiet low-tech lives in a closed community that is made up of exactly three hundred and fifty kind, ethical people living on exactly seven hundred hectares. When they climb through a hole in the perimeter fence to venture into the surrounding jungle, what they find is more astonishing than anything they could have imagined. And when Shelby realises the terrible danger that is unfolding, it will take all of her daring and determination to ensure the past does not repeat itself. Intriguing, absorbing and spine-tinglingly good, The Raven''s Song is a brilliant novel by two esteemed writers at the height of their powers.', 'verified', '163_the_ravens_song.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (164, 'A Glasshouse of Stars', 'Marr, Shirley', NULL, 'Meixing Lim and her family have arrived in the New Land to begin a New Life. Everything is scary and different. Their ever-changing house is confusing and she finds it hard to understand the other children at school. Yet in her magical glasshouse, with a strange black and white cat, Meixing finds a place to dream. But then Meixing''s life comes crashing down in unimaginable ways. Only her two new and unexpected friends can help. By being brave together, they will learn how to make the stars shine brighter. A Glasshouse of Stars is based on the author''s childhood and beautifully illustrates the importance of friendship, kindness and love. "Heart-twisting and hopeful, bursting with big feelings and gentle magic." Jessica Townsend, New York Times bestselling author of the Nevermoor series', 'verified', '164_a_glasshouse_of_stars.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (165, 'All Four Quarters of the Moon', 'Marr, Shirley', NULL, 'A big-hearted, magical story about sisterhood and a family finding their way in a new place, interwoven with Chinese mythology and a Little World made completely of paper, All Four Quarters of the Moon feels like an instant classic.The night of the Mid-Autumn festival, making mooncakes with Ah-Ma, was the last time Peijing Guo remembers her life being the same. Now adapting to their new life in Australia, Peijing thinks everything is going to turn out okay as long as they all have each other, but cracks are starting to appear in the family.Five-year-old Biju, lovable but annoying, needs Peijing to be the dependable big sister. Ah-Ma keeps forgetting who she is; Ma Ma is no longer herself and Ba Ba must adjust to a new role as a hands-on dad. Peijing has no idea how she''s supposed to cope with the uncertainties of her own world while shouldering the burden of everyone else.If her family are the four quarters of the mooncake, where does she even fit in?', 'verified', '165_all_four_quarters_of_the_moon.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (166, 'The Rabbits', 'Marsden, John', 'Shaun Tan', '"The rabbits came many grandparents ago. They built houses, made roads, had children. They cut down trees. A whole continent of rabbits ..."--Back cover.', 'verified', '166_the_rabbits.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (167, 'Eww Gross - Foul Facts and Putrid Pictures', 'Marshall, Dan', NULL, 'Did you know your kitchen is dirtier than your toilet seat? Or that there is a mound of poo bigger than the Statue of Liberty? And that there is a parasitic fungus that turns ants into zombies? This is a disgustingly wonderful guide to all things yuck, filled to the brim with facts and activities that will make you say Ewwww Gross!', 'verified', '167_eww_gross_foul_facts_and_putrid_pictures.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (168, 'Max', 'Martin, Marc', NULL, 'Max and Bob are old friends. Max helps out in Bob''s shop, and in the evenings they go fishing together. Until one summer, when everything changes . . . From the winner of the 2013 Crichton Award for Australia''s best new illustrator comes this heartwarming story of enduring friendship. And chips.', 'verified', '168_max.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (169, 'A Year On Our Farm', 'Matthews, Penny', NULL, 'Every month of the year there are jobs to do on a small Australian farm. Fruit ripens, lambs are born, hay is harvested. A Year on Our Farm shows the passing of the seasons through the eyes of the children for whom the farm and all its animals is home.', 'verified', '169_a_year_on_our_farm.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (170, 'Deep - Dive in Hidden Worlds', 'McGeachin, Jess', NULL, 'What hidden worlds lie beneath your feet? Or in the deepest parts of the ocean, where not even sunlight can reach? Come on a journey to meet glowing deep-sea creatures, zombie-making fungi and the trillions of tiny workers that live inside your own body. But be warned, things can get a little strange in the deep... Deep is an illustrated non-fiction book that explores the places hardest to reach, from the molten depths of our planet to the frigid depths of outer space. Linking seemingly diverse subject matter, it invites the reader to explore worlds hidden from view.', 'verified', '170_deep_dive_in_hidden_worlds.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (171, 'Anemone is Not the Enemy', 'McGregor, Anna', NULL, 'All Anemone wants is a friend, but friends are hard to make when you accidentally sting everyone who comes near you. Perhaps Clownfish has a solution to the problem... A funny tale of mishap, misunderstanding, and the search for true friendship in an ocean rockpool.', 'verified', '171_anemone_is_not_the_enemy.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (172, 'How to Make a Bird', 'McKinlay, Meg', NULL, 'From award-winning author Meg McKinlay and celebrated artist Matt Ottley comes a moving and visually stunning picture book that celebrates the transformative power of the creative process from inception through recognition to celebration and releasing into the world. We shadow the protagonist as she contemplates the blue print of an idea, collects the things that inspire from the natural world to shape a bird. And breathes life into it before letting it fly free. Sometimes small things, combined with a little imagination and a steady heart, can transform into works of magic.', 'verified', '172_how_to_make_a_bird.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (173, 'Ten Tiny Things', 'McKinlay, Meg', NULL, 'Tessa and Zachary travel to school by car ever day in cool calm comfort. But one morning, the car breaks down. Tessa and Zachary are forced to venture into the world beyond its metal walls - a place of secret somethings and hidden happenings and they discover everything they have been missing. Getting from here to there may never be the same ...', 'verified', '173_ten_tiny_things.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (174, 'There''s No Such Thing', 'McKinnon, Heidi', NULL, 'Bear can''t sleep. Did you hear that? Did you feel that? What was it? It wasn''t a hungry giant or a blood-sucking spider or a fire-breathing dragon because there is NO SUCH THING... Is there?', 'verified', '174_theres_no_such_thing.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (175, 'Day Break', 'McQuire, Amy', NULL, 'Day Break is the story of a family making their way back to Country on January 26. We see the strength they draw from being together, and from sharing stories as they move through a shifting landscape. The story refocuses the narratives around ‘Australia Day’ on Indigenous survival and resistance, and in doing so honours the past while looking to the future. Confronting yet truthful, painful yet full of hope, Day Break is a crucial story that will open up a conversation on truth-telling for the next generation.', 'verified', '175_day_break.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (176, 'Mutt Dog!', 'King, Stephen Mihael', NULL, 'A lonely dog has to make it on his own . . . until he finds the perfect home.', 'verified', '176_mutt_dog.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (177, 'Refugees', 'Miller, David', NULL, 'Two ducks are forced out of their swampy home by developers and search far and wide for a new place to live.', 'verified', '177_refugees.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (178, 'My Mama Had a Dancing Heart', 'Moore Gray, Libba', NULL, 'A ballet dancer recalls how she and her mother would welcome each season with a dance outdoors.', 'verified', '178_my_mama_had_a_dancing_heart.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (179, 'The Stolen Prince of Cloudburst', 'Moriarty, Jaclyn', NULL, 'This CBCA Honour Book is a magical tale of mystery and adventure that proves that sometimes even ordinary middle children can be heroes, from the bestselling author of The Extremely Inconvenient Adventures of Bronte Mettlestone and the award-winning The Slightly Alarming Tale of the Whispering Wars. HONOUR BOOK: 2021 CBCA Book of the Year, Younger Readers SHORT-LISTED: 2021 Prime Minister''s Literary Awards, Children''s Literature SHORT-LISTED: 2021 Queensland Literary Awards, Children''s Book Award Long ago, the little Prince of Cloudburst was stolen from the seashore by a Water Sprite. Now, ten years later, the prince has found his way home. The King and Queen are planning the biggest party in their Kingdom''s history to welcome him. Meanwhile, on the other side of the Kingdoms and Empires, Esther Mettlestone-Staranise is looking forward to another year at Katherine Valley Boarding School. But she arrives to find a number of strange and unsettling changes. For one, her new teacher is rumoured to be an Ogre. Two mysterious students have joined the school, and one of Esther''s classmates is an undercover Spellbinder. Most disturbingly, the mountains surrounding the school - usually a delight of glaciers, teashops, lakes and Faeries - are now crowded with wicked Shadow Mages. As secrets and dangers escalate, Esther must find the answers to several puzzles. Why is her teacher behaving so oddly? Which of Esther''s classmates is the Spellbinder, and can they really protect the school from gathering hordes of Shadow Mages? Could the Stolen Prince of Cloudburst be connected? How can Esther - who is not talented like her sisters, nor an adventurer like her cousin, but just Esther - save her family, her school and possibly her entire world?', 'verified', '179_the_stolen_prince_of_cloudburst.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (180, 'The Paper Bag Princess', 'Munsch, Robert', 'Michael Martchenko', 'After her castle and clothes are destroyed by the dragon, Princess Elizabeth, dressed only in a paper bag, sets out to rescue Prince Ronald, who was taken captive.', 'verified', '180_the_paper_bag_princess.jpg');
